package co.aura.voice

import co.aura.core.logging.AuraLogger
import co.aura.core.logging.LogCategory
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch

/**
 * Sequential Text-To-Speech queue player.
 *
 * Consumes sentence chunks one by one, allowing TTS to start immediately on the first sentence
 * while subsequent sentences are being generated by the LLM stream.
 *
 * Supports instant cancellation / interruption:
 * - immediately cancels playback coroutine
 * - stops the underlying TextToSpeechEngine
 * - clears all remaining queued sentences
 */
interface TtsQueuePlayer {
    val isPlaying: Boolean
    fun enqueue(chunk: String)
    fun enqueue(chunk: String, requestId: Long) { enqueue(chunk) }
    fun finishEnqueuing()
    fun finishEnqueuing(requestId: Long) { finishEnqueuing() }
    fun stopAndClear()
}

class DefaultTtsQueuePlayer(
    private val ttsEngine: TextToSpeechEngine,
    private val coroutineScope: CoroutineScope,
    private val onUtteranceStart: ((String) -> Unit)? = null,
    private val onUtteranceEnd: ((String) -> Unit)? = null,
    private val onPlaybackComplete: (() -> Unit)? = null,
    private val onPlaybackCompleteWithId: ((Long) -> Unit)? = null
) : TtsQueuePlayer {

    @Volatile
    private var _isPlaying = false
    override val isPlaying: Boolean get() = _isPlaying

    @Volatile
    private var currentRequestId: Long = 0L

    private var channel = Channel<String>(Channel.UNLIMITED)
    private var consumerJob: Job? = null
    private val lock = Any()

    private fun ensureConsumerRunning() {
        if (consumerJob?.isActive == true) return
        consumerJob = coroutineScope.launch {
            val reqIdAtStart = currentRequestId
            try {
                for (chunk in channel) {
                    if (!isActive) break
                    val text = chunk.trim()
                    if (text.isEmpty()) continue

                    _isPlaying = true
                    AuraLogger.i(LogCategory.VOICE, "[TTS_QUEUE] Playback START: \"$text\"")
                    onUtteranceStart?.invoke(text)

                    val formatted = SpeechTextFormatter.format(text)
                    AuraLogger.d(LogCategory.VOICE, "[TTS_QUEUE] Speaking chunk: \"$text\"")
                    val completed = ttsEngine.speak(formatted)
                    AuraLogger.d(LogCategory.VOICE, "[TTS_QUEUE] Finished chunk (success=$completed): \"$text\"")

                    onUtteranceEnd?.invoke(text)
                }
            } catch (e: CancellationException) {
                AuraLogger.d(LogCategory.VOICE, "[TTS_QUEUE] Playback job cancelled")
            } catch (e: Exception) {
                AuraLogger.e(LogCategory.VOICE, "[TTS_QUEUE] Error during playback", e)
            } finally {
                _isPlaying = false
                synchronized(lock) {
                    AuraLogger.i(LogCategory.VOICE, "[TTS_QUEUE] Playback COMPLETE")
                    // Reset channel for next turn so it is never left in a closed state
                    channel = Channel(Channel.UNLIMITED)
                    consumerJob = null
                }
                onPlaybackComplete?.invoke()
                onPlaybackCompleteWithId?.invoke(reqIdAtStart)
            }
        }
    }

    override fun enqueue(chunk: String) {
        enqueue(chunk, currentRequestId)
    }

    override fun enqueue(chunk: String, requestId: Long) {
        val trimmed = chunk.trim()
        if (trimmed.isEmpty()) return

        synchronized(lock) {
            currentRequestId = requestId
            // If channel was closed from a prior turn, immediately re-create it
            if (channel.isClosedForSend || channel.isClosedForReceive) {
                AuraLogger.d(LogCategory.VOICE, "[TTS_QUEUE] Channel was closed, re-creating Channel(UNLIMITED)")
                channel = Channel(Channel.UNLIMITED)
                consumerJob?.cancel()
                consumerJob = null
            }
            ensureConsumerRunning()
            AuraLogger.i(LogCategory.VOICE, "[TTS_QUEUE] Enqueued chunk: \"$trimmed\"")
            val sendResult = channel.trySend(trimmed)
            if (sendResult.isFailure) {
                AuraLogger.w(LogCategory.VOICE, "[TTS_QUEUE] Failed to enqueue chunk: \"$trimmed\"")
            }
        }
    }

    override fun finishEnqueuing() {
        finishEnqueuing(currentRequestId)
    }

    override fun finishEnqueuing(requestId: Long) {
        var notifyComplete = false
        val reqId = currentRequestId
        synchronized(lock) {
            AuraLogger.d(LogCategory.VOICE, "[TTS_QUEUE] Stream enqueuing finished. Closing channel for send.")
            channel.close()
            // If no consumer is running and nothing is playing, playback is already complete
            if (consumerJob?.isActive != true && !_isPlaying) {
                channel = Channel(Channel.UNLIMITED)
                consumerJob = null
                AuraLogger.i(LogCategory.VOICE, "[TTS_QUEUE] Playback COMPLETE (empty queue)")
                notifyComplete = true
            }
        }
        if (notifyComplete) {
            onPlaybackComplete?.invoke()
            onPlaybackCompleteWithId?.invoke(reqId)
        }
    }


    override fun stopAndClear() {
        synchronized(lock) {
            AuraLogger.i(LogCategory.VOICE, "[TTS_QUEUE] Immediate STOP and clear requested.")
            _isPlaying = false
            channel.close()
            consumerJob?.cancel()
            consumerJob = null
            ttsEngine.stop()

            // Prepare a fresh channel for the next turn
            channel = Channel(Channel.UNLIMITED)
        }
    }
}
